Method.Source:
[Form]
public class UPSAddPriceAttribute extends FormRun
{
    private FormRun                         sourceForm;
    private UPSPricingAttributeGroup        currentAttributeGroup;

    private UPSPricingAttributeGroupType    groupType;
    private UPSPricingAttributeSourceLevel  sourceLevel;
    private UPSPricingAttributeSource       currentSource;

    private SysFormEnumComboBox             sourceComboBox;

}

public void init()
{
    xArgs args = element.args();

    if (!element.args().caller())
    {
        element.lifecycleHelper().cancelFormInitialization(Exception::Error, error::wrongUseOfFunction(funcName()));
    }
    else
    {
        sourceForm = args.caller();
        currentAttributeGroup = args.record();
        UPSPricingAttributeGroup = currentAttributeGroup;
        groupType = currentAttributeGroup.GroupType;
        sourceLevel = currentAttributeGroup.SourceLevel;
    }

    element.initControls();

    super(); 

    element.setControls();             
}

private void initControls()
{
    Set enumSet = element.getSourceEnumForScope();

    if (groupType == UPSPricingAttributeGroupType::General)
    {            
        sourceComboBox = SysFormEnumComboBox::newParameters(
                element,
                element.controlId(formControlStr(UPSAddPriceAttribute, PricingAttributeGroup_GroupType)),
                enumnum(UPSPricingAttributeSource),
                enumSet,
                "@UnifiedPricingService:UPSPricingAttributeSourceName");
    }
}

private void setControls()
{
    PricingAttributeGroup_SourceLevel.allowEdit(false);
    PricingAttributeGroup_SourceLevel.text(enum2Str(sourceLevel));

    switch (groupType)
    {
        case UPSPricingAttributeGroupType::Customer:
            PricingAttributeGroup_GroupType.allowEdit(false);
            PricingAttributeGroup_GroupType.selection(enum2int(UPSPricingAttributeSource::Customer));
            break;

        case UPSPricingAttributeGroupType::Product:
            PricingAttributeGroup_GroupType.allowEdit(false);
            PricingAttributeGroup_GroupType.selection(enum2int(UPSPricingAttributeSource::Product));
            break; 

        default:
            if (sourceLevel == UPSPricingAttributeSourceLevel::Header)
            {
                sourceComboBox.select(enum2int(UPSPricingAttributeSource::Customer));
                currentSource = UPSPricingAttributeSource::Customer;
            }
            else if (sourceLevel == UPSPricingAttributeSourceLevel::Line)
            {
                sourceComboBox.select(enum2int(UPSPricingAttributeSource::Product));
                currentSource = UPSPricingAttributeSource::Product;
            }
    }       
}

private Set getSourceEnumForScope()
{
    Set enumSet = new Set(Types::Enum);
    switch (sourceLevel)
    {
        case UPSPricingAttributeSourceLevel::Header:
            enumSet.add(UPSPricingAttributeSource::Customer);
            enumSet.add(UPSPricingAttributeSource::CustomerPriceGroup);
            enumSet.add(UPSPricingAttributeSource::SalesTable);                
            break;

        case UPSPricingAttributeSourceLevel::Line:
            enumSet.add(UPSPricingAttributeSource::Product);
            enumSet.add(UPSPricingAttributeSource::ProductPriceGroup);
            enumSet.add(UPSPricingAttributeSource::SalesLine);
            break;
    }
    return enumSet;
}

private void initPriceAttributeTmp()
{
    select firstonly RecId from UPSPricingAttributeTmp;
    if (!UPSPricingAttributeTmp.RecId)
    {
        List attributes = UPSPricingAttributeRepository::getAllPricingAttributes();

        ttsbegin;

        Enumerator enum = attributes.getEnumerator();

        UPSIPricingAttribute pricingAttr;
        UPSPricingAttributeLink link;
        int cnt = 1;
        DictClass dc;

        while (enum.moveNext())
        {
            pricingAttr = enum.current();
            link = UPSPricingAttributeRepository::toPriceAttributeLink(pricingAttr);
            UPSPricingAttributeTmp.AttributeName = link.AttributeName;
            UPSPricingAttributeTmp.PriceAttributeClassId = link.PriceAttributeClassId;
            UPSPricingAttributeTmp.TypeName = link.TypeName;
            UPSPricingAttributeTmp.ProviderClassId = link.AttributeProviderClassId;
            UPSPricingAttributeTmp.Id = cnt;
            dc = link.PriceAttributeClassId == classNum(UPSPricingAttributeEcoResAttribute) ? new DictClass(link.AttributeProviderClassId) : new DictClass(link.PriceAttributeClassId);
            UPSPricingAttributeTmp.Level = (dc.getAttribute('UPSPricingAttributeSourceDiscoveryAttribute') as UPSPricingAttributeSourceDiscoveryAttribute).parmLevel();
            UPSPricingAttributeTmp.Source = link.getPriceAttributeSourceSymbol();
            UPSPricingAttributeTmp.Table = pricingAttr.getQueryBuilderDatasourceIdentifier();
            UPSPricingAttributeTmp.PriceAttributeClassName = classId2Name(link.PriceAttributeClassId);
            UPSPricingAttributeTmp.insert();
            cnt++;
        }
        ttscommit;
    }
}

public void executeQuery()
{
    Query query = new Query();
    QueryBuildDataSource        queryBuildDataSource;
    QueryBuildRange             queryBuildRange;
    QueryBuildRange             queryBuildRangeSource;

    element.initPriceAttributeTmp();      
    queryBuildDataSource = query.addDataSource(tablenum(UPSPricingAttributeTmp));

    // Filter by SourceLevel
    queryBuildRange = queryBuildDataSource.addRange(fieldNum(UPSPricingAttributeTmp, Level));
    queryBuildRange.value(PricingAttributeGroup_SourceLevel.valueStr());

    // Filter by GroupType
    switch (groupType)
    {
        case UPSPricingAttributeGroupType::Customer:
            queryBuildRangeSource = queryBuildDataSource.addRange(fieldNum(UPSPricingAttributeTmp, Source));
            queryBuildRangeSource.value(enum2Symbol(enumNum(UPSPricingAttributeSource), UPSPricingAttributeSource::Customer));
            break;

        case UPSPricingAttributeGroupType::Product:
            queryBuildRangeSource = queryBuildDataSource.addRange(fieldNum(UPSPricingAttributeTmp, Source));
            queryBuildRangeSource.value(enum2Symbol(enumNum(UPSPricingAttributeSource), UPSPricingAttributeSource::Product));
            break;

        case UPSPricingAttributeGroupType::General:
            queryBuildRangeSource = queryBuildDataSource.addRange(fieldNum(UPSPricingAttributeTmp, Source));
            queryBuildRangeSource.value(enum2Symbol(enumNum(UPSPricingAttributeSource), element.currentSource));
    }

    this.query(query);
    super();
}

public boolean modified()
{
    boolean ret;

    ret = super();

    UPSPricingAttributeSource sourceType;
    element.currentSource = str2Enum(sourceType, this.valueStr());

    UPSPricingAttributeTmp_ds.executeQuery();

    return ret;
}

public void clicked()
{
    super();

    if (UPSPricingAttributeGroup::isPricingAttributeGroupUsed(currentAttributeGroup.RecId))
    {
        warning("@UnifiedPricingService:UPSPricingAttributeGroupIsUsed");
        return;
    }

    ttsbegin; 

    UPSPricingAttributeTmp attributeTmp;
    UPSPricingAttributeLink link;

    int priority = this.getHighestPriority();

    for (attributeTmp = UPSPricingAttributeTmp_ds.getFirst(true) ? UPSPricingAttributeTmp_ds.getFirst(true) : UPSPricingAttributeTmp_ds.cursor();
         attributeTmp;
         attributeTmp = UPSPricingAttributeTmp_ds.getNext())
    {
        link.PriceAttributeGroup = currentAttributeGroup.RecId;
        link.PriceAttributeClassId = attributeTmp.PriceAttributeClassId;
        link.AttributeName = attributeTmp.AttributeName;
        link.AttributeProviderClassId = attributeTmp.ProviderClassId;
        link.TypeName = attributeTmp.TypeName;
        UPSPricingAttributeSource sourceType;
        link.Source = str2Enum(sourceType, attributeTmp.Source);
        link.Priority = priority;
        link.insert();    
        priority++;
    }

    ttscommit;         
}

public int getHighestPriority()
{
    UPSPricingAttributeLink link;
    select firstonly Priority from link order by Priority desc
        where link.PriceAttributeGroup == UPSPricingAttributeLink.PriceAttributeGroup;
    return link.Priority + 1;
}
